    private void initializeWorkspace(Bundle state) {
        getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);
        autosave=new File(getFilesDir(),"autosave.fcml");
        previousCommand=getSharedPreferences("commands",MODE_PRIVATE).getString("last","");
        String history=getSharedPreferences("commands",MODE_PRIVATE).getString("history","");for(String c:history.split("\n"))if(!c.isEmpty()&&commandHistory.size()<20)commandHistory.add(c);
        exportTolerance=getSharedPreferences("viewport",MODE_PRIVATE).getFloat("export_tolerance",.015f);if(exportTolerance<.005||exportTolerance>.5)exportTolerance=.015;
        previewBudget=getSharedPreferences("viewport",MODE_PRIVATE).getInt("triangle_budget",50000);
        if(previewBudget<1000||previewBudget>200000)previewBudget=50000;
        android.content.SharedPreferences viewPrefs=getSharedPreferences("viewport",MODE_PRIVATE);automaticDetail=viewPrefs.getBoolean("auto_detail",false);pngSize=viewPrefs.getInt("png_size",1024);if(pngSize<512||pngSize>2048)pngSize=1024;pngTransparent=viewPrefs.getBoolean("png_alpha",false);try{rendering=new RenderSettings(viewPrefs.getInt("style",0),viewPrefs.getBoolean("clip",false),Double.parseDouble(viewPrefs.getString("clip_z","0")),false);}catch(Exception ignored){rendering=RenderSettings.DEFAULT;}
        if(state!=null){batchNode=state.getInt("batch_node");batchCount=state.getInt("batch_count");batchFirst=state.getDouble("batch_first");batchLast=state.getDouble("batch_last");exportFormat=state.getString("export_format","stl");exportSelection=state.getInt("export_selection",0);pendingExportRestoreId=Math.max(0,exportSelection);}
        File[] recoveries=getFilesDir().listFiles(f->f.getName().startsWith("autosave-recovery-")&&f.getName().endsWith(".fcml"));
        if(recoveries!=null)for(File f:recoveries)if(recoveryFile==null||f.lastModified()>recoveryFile.lastModified())recoveryFile=f;
        Diagnostics.stage(this,"Building software-capable UI");buildUi();
        job("Opening workspace",()->{
            if(getIntent().getBooleanExtra("empty_workspace",false)) {
                if(autosave.isFile()){recoveryFile=new File(getFilesDir(),"autosave-recovery-"+System.currentTimeMillis()+".fcml");java.nio.file.Files.copy(autosave.toPath(),recoveryFile.toPath());startupNotice="The previous saved workspace was kept as a recovery copy. Use Workspace > Export recovery copy to retrieve it.";}
                Diagnostics.stage(this,"Starting empty workspace");NativeCad.clear();selected=0;ProjectStore.reset();
            }else if(autosave.isFile()) {
                Diagnostics.stage(this,"Restoring saved workspace");
                try{if(ProjectStore.schemaVersion(autosave)==1){recoveryFile=new File(getFilesDir(),"autosave-recovery-v1-"+System.currentTimeMillis()+".fcml");java.nio.file.Files.copy(autosave.toPath(),recoveryFile.toPath());startupNotice="A legacy project recovery copy was kept before upgrading autosave to project version 2. Export it from Workspace if needed.";}loadProject(autosave);}
                catch(Exception e) {
                    // Preserve the bad file before any new autosave can replace it.
                    recoveryFile=new File(getFilesDir(),"autosave-recovery-"+System.currentTimeMillis()+".fcml");
                    java.nio.file.Files.copy(autosave.toPath(),recoveryFile.toPath());
                    NativeCad.rollbackTransaction();NativeCad.beginTransaction(false);NativeCad.clear();ProjectStore.reset();
                    selected=NativeCad.create("Ring",new double[]{18,1.6,3});
                    startupNotice="The saved workspace could not be opened. A recovery copy was kept. Use Workspace > Export recovery copy to retrieve it.";
                }
            }else{Diagnostics.stage(this,"Creating initial ring");NativeCad.clear();ProjectStore.reset();selected=NativeCad.create("Ring",new double[]{18,1.6,3});}
            if(pendingExportRestoreId>0){exportSelection=-1;pendingExportRestoreId=0;}
        },true,false,true);
        if(getIntent().getBooleanExtra("run_selftests",false))worker.execute(()->{
            try{File f=new File(getFilesDir(),"selftest.txt");f.delete();String r=NativeCad.selfTest(getFilesDir().getAbsolutePath());writeText(f,r);android.util.Log.i("CAD_SELFTEST",r);}catch(Throwable t){android.util.Log.e("CAD_SELFTEST","FAIL",t);}
        });
    }
