    private void submitCommand(){
        if(busy||destroyed)return;String input=commandInput.getText().toString().trim();if(input.isEmpty())input=previousCommand;
        try{CommandLine.Request request=CommandLine.parse(input);previousCommand=input;commandHistory.add(0,input);while(commandHistory.size()>20)commandHistory.remove(commandHistory.size()-1);getSharedPreferences("commands",MODE_PRIVATE).edit().putString("last",input).putString("history",android.text.TextUtils.join("\n",commandHistory)).apply();commandInput.setText("");commandInput.clearFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(commandInput.getWindowToken(),0);
            if(request.ui()){openCommandTool(request);return;}if(request.name.equals("Undo")||request.name.equals("Redo")||request.name.equals("Select"))subelementIndex=0;final int id=selected;job("Command: "+input,()->selected=CommandLine.execute(request,id),!request.name.equals("Select"),request.recordUndo(),!request.name.equals("Select"));
        }catch(Exception e){alert("Command",e.getMessage());}
    }
    private String objectName(JSONObject o){String name=o.optString("name","");return name.isEmpty()?o.optString("type"):name;}
    private void historyStep(boolean redo){job(redo?"Redo":"Undo",()->{if(!(redo?NativeCad.redo():NativeCad.undo()))throw new IllegalArgumentException("No change to "+(redo?"redo":"undo"));ProjectStore.applyWorkspace(NativeCad.getWorkspace());},false,false,true);}
    private void pickObject(double[] ray){if(busy||destroyed)return;job("Select model",()->{int id;if(subelementKind>0){int[] hit=NativeCad.pickElement(ray,subelementKind);id=hit[0];subelementIndex=hit[2];}else{id=NativeCad.pickFiltered(ray,selectionFilter);subelementIndex=0;}if(id>0){selected=id;if(multipleSelection){if(!selectionSet.add(id))selectionSet.remove(id);}else{selectionSet.clear();selectionSet.add(id);}}},false,false,false);}
