    private int[] selectionIds(){if(selectionSet.isEmpty())selectionSet.add(selected);int[] ids=new int[selectionSet.size()];int i=0;for(int id:selectionSet)ids[i++]=id;return ids;}
    private void chooseMultiple(){String[] names=new String[data.length()];int[] ids=new int[names.length];boolean[] checked=new boolean[names.length];for(int i=0;i<names.length;i++){JSONObject o=data.optJSONObject(i);ids[i]=o.optInt("id");names[i]=objectName(o)+" #"+ids[i];checked[i]=selectionSet.contains(ids[i]);}new UiDialog(this).setTitle("Multiple objects").setMultiChoiceItems(names,checked,(d,w,on)->checked[w]=on).setNegativeButton("Cancel",null).setPositiveButton("Select",(d,w)->{selectionSet.clear();for(int i=0;i<ids.length;i++)if(checked[i]){selectionSet.add(ids[i]);selected=ids[i];}multipleSelection=true;job("Multiple selection",()->{},false,false,false);}).show();}
