    private void graphicsFailure(String message) {
        if(destroyed)return;Diagnostics.error(this,"Graphics startup/drawing",new IllegalStateException(message));
        if(viewport instanceof CadView){ModelViewport old=viewport;old.onPause();modelStage.removeView(old.view());old.close();viewport=new SoftwareCadView(this,m->{if(!destroyed)alert("Software 3D",m);});viewport.settings(rendering);viewport.setFrameListener(this::frameTiming);viewport.setPickListener(this::pickObject);viewport.setOrientationListener(viewCube::angles);modelStage.addView(viewport.view(),0,new FrameLayout.LayoutParams(-1,-1));if(lastMesh!=null)viewport.setMesh(lastMesh,true);rendererError=message;if(status!=null)L10n.setText(status,"Software 3D active");Toast.makeText(this,L10n.text(this,"Switched to software 3D"),Toast.LENGTH_LONG).show();}
        else alert("3D view",message);
    }
