    private void alert(String title,String message){if(!destroyed)new UiDialog(this).setTitle(title).setMessage(message).setPositiveButton("OK",null).show();}
    private interface Task{void run() throws Exception;}
    private void setBusy(boolean value,String message) {
        busy=value;for(Button b:controls)b.setEnabled(!value);
        for(int i=0;i<tree.getChildCount();i++)tree.getChildAt(i).setEnabled(!value);
        if(commandInput!=null)commandInput.setEnabled(!value);if(progress!=null)progress.setVisibility(value?View.VISIBLE:View.GONE);
        L10n.setText(status,message);
    }
    private void resumePendingResult(){if(!busy&&pendingResult!=null&&!destroyed){Runnable action=pendingResult;pendingResult=null;action.run();}flushGraph();}
    private void job(String label,Task action,boolean fit){job(label,action,fit,true,true);}
    private void job(String label,Task action,boolean fit,boolean recordUndo,boolean persist) {
        job(label,action,fit,recordUndo,persist,null);
    }
    private void job(String label,Task action,boolean fit,boolean recordUndo,boolean persist,Runnable onSuccess) {
        if(busy||destroyed)return;if(recordUndo||label.equals("Undo")||label.equals("Redo")||label.equals("Opening workspace"))subelementIndex=0;setBusy(true,label+"…");int previousSelection=selected;
        worker.execute(()->{
            long jobStart=System.nanoTime();boolean active=false;String previousWorkspace=null;
            try {
                previousWorkspace=ProjectStore.workspace();Diagnostics.stage(this,label+": loading native libraries / transaction");NativeCad.beginTransaction(recordUndo);active=true;action.run();
                Diagnostics.stage(this,label+": reading model metadata");
                JSONArray next=new JSONArray(NativeCad.objects());boolean exists=false;
                for(int i=0;i<next.length();i++)if(next.getJSONObject(i).getInt("id")==selected)exists=true;
                if(!exists)selected=next.length()>0?next.getJSONObject(next.length()-1).getInt("id"):0;
                Diagnostics.stage(this,label+": tessellating display mesh");float[] vertices=NativeCad.meshAtDetail(selected,previewBudget);
                // Validate the bounded display mesh before committing the model change.
                MeshFrame mesh=new MeshFrame(vertices,NativeCad.lines(selected),NativeCad.surfaceValues());
                if(recordUndo||label.equals("Opening workspace"))NativeCad.setWorkspace(ProjectStore.workspace());NativeCad.commitTransaction();active=false;
                String saveWarning=null;
                if(persist)try{saveProject(autosave);}catch(Exception e){saveWarning="The model changed, but autosave failed: "+e.getMessage();}
                final String warning=saveWarning;
                runOnUiThread(()->{
                    if(destroyed)return;lastJobMs=(System.nanoTime()-jobStart)/1000000;data=next;lastMesh=mesh;viewport.setMesh(mesh,fit);setBusy(false,"Ready");refresh(mesh.count/3);Diagnostics.stage(this,"Workspace ready");
                    if(rendererError!=null)L10n.setText(status,"Software 3D active after graphics failure");
                    if(warning!=null)alert("Autosave",warning);
                    if(startupNotice!=null){String notice=startupNotice;startupNotice=null;alert("Workspace recovery",notice);}
                    if(onSuccess!=null)onSuccess.run();resumePendingResult();
                });
            }catch(Throwable t) {
                if(active)try{NativeCad.rollbackTransaction();}catch(Throwable recovery){android.util.Log.e("CAD_ENGINE","Rollback failed",recovery);}
                selected=previousSelection;if(previousWorkspace!=null)try{ProjectStore.applyWorkspace(previousWorkspace);}catch(Exception stateError){android.util.Log.e("CAD_ENGINE","Recipe rollback failed",stateError);}Diagnostics.error(this,label,t);android.util.Log.e("CAD_ENGINE",label+" failed",t);
                runOnUiThread(()->{if(destroyed)return;setBusy(false,"Operation failed");alert("CAD operation",t.getMessage()==null?t.toString():t.getMessage());resumePendingResult();});
            }
        });
    }
    private JSONObject current(){for(int i=0;i<data.length();i++){JSONObject o=data.optJSONObject(i);if(o!=null&&o.optInt("id")==selected)return o;}return null;}
    private void refresh(int triangles) {
        tree.removeAllViews();java.util.Set<Integer> live=new java.util.HashSet<>();for(int i=0;i<data.length();i++)live.add(data.optJSONObject(i).optInt("id"));selectionSet.retainAll(live);
        for(int i=0;i<data.length();i++) {
            JSONObject o=data.optJSONObject(i);int id=o.optInt("id");
            Button chip=new Button(this);chip.setAllCaps(false);chip.setTextSize(12);chip.setText((selectionSet.contains(id)&&multipleSelection?"✓ ":"")+(o.optBoolean("visible")?"● ":"○ ")+objectName(o)+" "+id+(o.optBoolean("locked")?" 🔒":""));chip.setTextColor(id==selected?BG:INK);chip.setBackground(round(id==selected?ACCENT:PANEL));
            LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(42));p.setMargins(dp(3),0,dp(3),0);tree.addView(chip,p);
            chip.setOnClickListener(v->{if(busy)return;selected=id;subelementIndex=0;if(multipleSelection){if(!selectionSet.add(id))selectionSet.remove(id);}else{selectionSet.clear();selectionSet.add(id);}job("Selecting",()->{},false,false,false);});chip.setOnLongClickListener(v->{if(busy)return true;selected=id;objectMenu(o);return true;});
        }
        JSONObject o=current();
        if(o==null){L10n.setText(selectionLabel,"Empty workspace · create or import a model");L10n.setText(status,"All measurements in millimetres");return;}
        L10n.setText(selectionLabel,objectName(o)+" "+selected+(subelementIndex>0?" · "+new String[]{"","face","edge","vertex"}[subelementKind]+" #"+subelementIndex:"")+(multipleSelection?" · "+selectionSet.size()+" selected":"")+(o.optBoolean("visible")?"":" · hidden"));
        JSONArray b=o.optJSONArray("bounds");double volume=o.optDouble("volume");
        L10n.setText(status,String.format(Locale.US,L10n.text(this,"%.2f × %.2f × %.2f mm   ·   %s   ·   %,d triangles"),b.optDouble(0),b.optDouble(1),b.optDouble(2),o.optBoolean("mesh")?"mesh":o.optBoolean("curve")?"CAD curve / profile":o.optBoolean("solid")?String.format(Locale.US,L10n.text(this,"%.2f mm³"),volume):"CAD surface / shell",triangles));
        if(o.optBoolean("mesh"))L10n.setText(status,String.format(Locale.US,L10n.text(this,"%.2f × %.2f × %.2f mm\n%,d original triangles · %,d scene preview triangles"),b.optDouble(0),b.optDouble(1),b.optDouble(2),o.optLong("sourceTriangles"),triangles));
    }
