        if(w==0)new UiDialog(this).setTitle("Basic solids").setItems(L10n.labels(this,new String[]{"Ring","Box","Cylinder","Sphere","Torus","Sketch pad"}),(x,i)->{String k=new String[]{"Ring","Box","Cylinder","Sphere","Torus","Sketch pad"}[i];dimensions(k,defaults(k),false);}).show();
