    private void menu() {
        ArrayList<String> items=new ArrayList<>();items.add("Save project (.fcml)");items.add("New workspace");items.add("Run kernel tests");items.add("About / licences");
        items.add("Crash report / recovery");items.add("Offline guide");items.add("Reference samples");if(recoveryFile!=null&&recoveryFile.isFile())items.add("Export recovery copy");
        items.add("FreeCAD document lab");items.add("Language");
        new UiDialog(this).setTitle("Workspace").setItems(L10n.labels(this,items.toArray(new String[0])),(d,w)->{
            if(items.get(w).equals("Language")){L10n.picker(this);return;}
            if(items.get(w).equals("FreeCAD document lab")){startActivity(new Intent(this,CoreDocumentActivity.class));return;}
            if(w==0)createDocument(SAVE,"model.fcml");
            if(w==1)new UiDialog(this).setTitle("New workspace?").setMessage("The current workspace will be cleared. Undo can recover it during this session.").setNegativeButton("Cancel",null).setPositiveButton("New",(x,y)->job("New",()->{NativeCad.clear();selected=0;ProjectStore.reset();},true)).show();
            if(w==2)runKernelTests();if(w==3)about();if(w==4)recoveryScreen();if(w==5)guideDialog();if(w==6)samplesDialog();if(w==7)createDocument(RECOVERY,"autosave-recovery.fcml");
        }).show();
    }
    private void createDocument(int request,String filename){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(i,request);}
    private void runKernelTests() {
        if(busy||destroyed)return;setBusy(true,"Testing kernel…");
        worker.execute(()->{
            try {
                File f=new File(getFilesDir(),"selftest.txt");f.delete();String result=NativeCad.selfTest(getFilesDir().getAbsolutePath());writeText(f,result);
                runOnUiThread(()->{if(destroyed)return;setBusy(false,"Kernel tests passed");alert("Kernel tests",result);resumePendingResult();});
            }catch(Throwable t){runOnUiThread(()->{if(destroyed)return;setBusy(false,"Kernel test failed");alert("Kernel tests",t.toString());resumePendingResult();});}
        });
    }
    private void about(){alert("FreeCAD Mobile Lab · "+ReleaseInfo.VERSION, "Independent native Android CAD app with selected FreeCAD functionality.\n\nNative ARM64 OpenCASCADE 7.9.2 CAD kernel; actual FreeCAD PlaneGCS Sketcher solver; software 3D renderer, optional OpenGL ES 3, and Android touch UI.\n\nNew: weighted NURBS control points, interpolated splines, profiles, loft/sweep/revolve/extrude, sections, offsets, chamfer, healing, jewellery settings, bounded subdivision primitives and a small typed node graph.\n\nThe optional document lab includes original FreeCAD Base/App/Part/Materials/Sketcher/PartDesign, native parametric solids and booleans, dimensional expressions, transactions, bounded geometry preview, STEP exchange, Python console/macros and one portable scripted metadata feature. Native FCStd restoration is limited to documented App metadata, whitelisted Part/Sketcher types and bounded original Body/Pad/Pocket/Revolution/Groove/Loft and finishing workflows. Broader PartDesign, Gui and arbitrary workbench/addon FCStd support remain pending. This version requires Android execution testing. The main CAD workspace keeps its independent OCCT recipe engine. STEP transfers solid geometry to desktop FreeCAD.\n\nAll work is local. The app requests no network permission.\n\nCode: LGPL-2.1-or-later. FreeCAD: LGPL-2.1-or-later. OpenCASCADE: LGPL-2.1 with OCCT exception. Eigen: MPL-2.0. Boost: Boost Software License 1.0. meshoptimizer: MIT. Optional lab: Qt6.8.3 LGPL3/GPL3 notices and CPython3.13 PSF licence. Full notices accompany the source bundle and are included in app assets.");}
