    private void curveEditor(String kind,String initial,int replaceId){
        LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(16),dp(8),dp(16),dp(8));panel.addView(text("One point per line: X Y Z [weight]. Millimetres.\nNURBS follows control points; interpolation passes through points. Maximum 64 points.",12,MUTED));EditText points=new EditText(this);points.setTextColor(INK);points.setText(initial);points.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);points.setMinLines(5);panel.addView(points);CheckBox closed=new CheckBox(this);closed.setText("Closed curve");closed.setTextColor(INK);closed.setEnabled(!kind.equals("NURBS curve"));panel.addView(closed);ScrollView scroll=new ScrollView(this);scroll.addView(panel);
        AlertDialog dialog=new UiDialog(this).setTitle((replaceId>0?"Edit ":"Create ")+kind).setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Apply",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{try{String raw=points.getText().toString();if(raw.length()>12000)throw new IllegalArgumentException("Too much point data");String[] rows=raw.trim().split("[\\r\\n;]+");if(rows.length<2||rows.length>64)throw new IllegalArgumentException("Enter 2 to 64 points");double[] values=new double[rows.length*4];for(int i=0;i<rows.length;i++){String[] xyz=rows[i].trim().split("[\\s,]+");if(xyz.length!=3&&xyz.length!=4)throw new IllegalArgumentException("Each line needs X Y Z and an optional weight");for(int j=0;j<4;j++){values[i*4+j]=j==3&&xyz.length==3?1:Double.parseDouble(xyz[j]);if(!Double.isFinite(values[i*4+j]))throw new IllegalArgumentException("Points must be finite");}}dialog.dismiss();job(kind,()->selected=FeatureModel.curve(kind,values,closed.isChecked(),replaceId),true);}catch(Exception error){Toast.makeText(this,L10n.text(this,error.getMessage()),Toast.LENGTH_LONG).show();}}));dialog.show();
    }
