    private String name(Uri uri){try(android.database.Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}return "model";}
    @Override protected void onActivityResult(int request,int result,Intent intent) {
        super.onActivityResult(request,result,intent);if(result!=RESULT_OK||intent==null||intent.getData()==null)return;
        Uri uri=intent.getData();Runnable action=()->handleFileResult(request,uri);
        if(busy)pendingResult=action;else action.run();
    }
    private void handleFileResult(int request,Uri uri) {
        if(request==SHEET_IMPORT){job("Import worksheet CSV",()->{File file=File.createTempFile("worksheet-",".csv",getCacheDir());try{try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){ArchiveIO.copy(in,out,Worksheet.MAX_CSV,null);}Worksheet.readCsv(file);}finally{file.delete();}},false);return;}
        if(request==IMPORT)job("Import",()->{
            String n=name(uri).toLowerCase(Locale.ROOT);
            String format=n.endsWith(".3mf")?"3mf":n.endsWith(".glb")?"glb":n.endsWith(".dxf")?"dxf":n.endsWith(".cadgraph")?"cadgraph":n.endsWith(".step")||n.endsWith(".stp")?"step":n.endsWith(".iges")||n.endsWith(".igs")?"iges":n.endsWith(".obj")?"obj":n.endsWith(".stl")?"stl":n.endsWith(".brep")?"brep":n.endsWith(".fcml")?"fcml":n.endsWith(".fcstd")?"fcstd":"";
            if(format.isEmpty())throw new IOException("Supported: STEP, IGES, OBJ, STL, simple 3MF/GLB meshes, ASCII DXF curves, BREP, saved FCStd Part geometry, .fcml projects and .cadgraph recipes.");
            File local=File.createTempFile("import-","."+format,getCacheDir());
            try {
                try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(local)){ArchiveIO.copy(in,out,ArchiveIO.MAX_TOTAL,null);}
                if(format.equals("dxf")){selected=DxfImporter.read(local);}else if(format.equals("glb")||format.equals("3mf")){File stl=File.createTempFile("mesh-",".stl",getCacheDir());try{if(format.equals("glb"))MeshFormats.readGlb(local,stl);else MeshFormats.read3mf(local,stl);selected=NativeCad.read(stl.getAbsolutePath(),"stl");}finally{stl.delete();}}else if(format.equals("cadgraph")){String json=RecipeFiles.read(local);selected=ParametricGraph.evaluate(json,ProjectStore.graphOutputIds);ProjectStore.graphJson=json;ProjectStore.graphOutputIds=ParametricGraph.lastOutputs.clone();}else if(format.equals("fcml"))loadProject(local);else if(format.equals("fcstd"))selected=FcstdImporter.read(local,getCacheDir());else selected=NativeCad.read(local.getAbsolutePath(),format);
            }finally{local.delete();}
        },true);
        if(request==EXPORT){final String format=exportFormat;final int exportId=exportSelection;job("Export",()->{
            if(exportId<0)throw new IOException("The export selection is unavailable after workspace recovery. Select an object and export again.");
            File local=File.createTempFile("export-","."+format,getCacheDir());
            try{if(format.equals("sheetcsv")){Worksheet.writeCsv(local);}else if(format.equals("sheet")){DrawingSheet.write(local,getCacheDir(),exportId,getSharedPreferences("drawing",MODE_PRIVATE).getString("title","CAD drawing"),getSharedPreferences("drawing",MODE_PRIVATE).getString("notes",""));}else if(format.equals("3mf")||format.equals("glb")){File stl=File.createTempFile("mesh-export-",".stl",getCacheDir());try{NativeCad.writeWithTolerance(stl.getAbsolutePath(),"stl",exportId,exportTolerance);if(format.equals("glb"))MeshFormats.glb(stl,local);else MeshFormats.threeMF(stl,local);}finally{stl.delete();}}else if(format.equals("cadgraph")){RecipeFiles.write(local,ProjectStore.graphJson);}else if(format.equals("variants")){RecipeFiles.batch(local,getCacheDir(),ProjectStore.graphJson,batchNode,batchFirst,batchLast,batchCount,exportTolerance);}else if(format.equals("png")){MeshFrame frame=new MeshFrame(NativeCad.meshAtDetail(0,150000),NativeCad.lines(0),NativeCad.surfaceValues());SoftwareRasterizer.Image image=SoftwareRasterizer.render(frame,pngSize,pngSize,-32,-58,1,0,0,false,rendering.alpha(pngTransparent));android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(image.pixels,image.width,image.height,android.graphics.Bitmap.Config.ARGB_8888);try(OutputStream out=new FileOutputStream(local)){if(!bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out))throw new IOException("PNG export failed");}finally{bitmap.recycle();}}else NativeCad.writeWithTolerance(local.getAbsolutePath(),format,exportId,exportTolerance);writeUri(local,uri);}finally{local.delete();}
        },false,false,false);}
        if(request==SAVE)job("Save project",()->{
            File local=File.createTempFile("project-",".fcml",getCacheDir());
            try{saveProject(local);writeUri(local,uri);}finally{local.delete();}
        },false,false,false);
        if(request==RECOVERY)job("Export recovery copy",()->{if(recoveryFile==null||!recoveryFile.isFile())throw new IOException("No recovery copy found");writeUri(recoveryFile,uri);},false,false,false);
    }
    private void writeUri(File source,Uri uri)throws IOException {
        if(source.length()>ArchiveIO.MAX_TOTAL)throw new IOException("Export exceeds the mobile size limit");
        try(InputStream in=new FileInputStream(source);OutputStream out=getContentResolver().openOutputStream(uri,"wt")){ArchiveIO.copy(in,out,ArchiveIO.MAX_TOTAL,null);}
        String filename=name(uri);runOnUiThread(()->{if(!destroyed)Toast.makeText(this,L10n.text(this,"Saved "+filename),Toast.LENGTH_LONG).show();});
    }
    private static void writeText(File f,String s)throws IOException{try(OutputStream out=new FileOutputStream(f)){out.write(s.getBytes(StandardCharsets.UTF_8));}}
    private void saveProject(File destination)throws Exception{ProjectStore.save(destination,getCacheDir());}
    private void loadProject(File source)throws Exception{java.util.Map<Integer,Integer> ids=new java.util.HashMap<>();selected=ProjectStore.restore(source,getCacheDir(),ids);if(pendingExportRestoreId>0){Integer restored=ids.get(pendingExportRestoreId);exportSelection=restored==null?-1:restored;pendingExportRestoreId=0;}}
    @Override protected void onSaveInstanceState(Bundle state){state.putInt("batch_node",batchNode);state.putInt("batch_count",batchCount);state.putDouble("batch_first",batchFirst);state.putDouble("batch_last",batchLast);state.putString("export_format",exportFormat);state.putInt("export_selection",exportSelection);super.onSaveInstanceState(state);}
    @Override protected void onPause(){super.onPause();if(viewport!=null)viewport.onPause();}
    @Override protected void onResume(){super.onResume();if(viewport!=null)viewport.onResume();}
    @Override protected void onDestroy(){destroyed=true;if(CrashApplication.graphicsFailure==graphicsListener)CrashApplication.graphicsFailure=null;if(viewport!=null)viewport.close();Diagnostics.stage(this,"Workspace closed");super.onDestroy();}
